-- NEXUS WORK V1 Supabase setup
create extension if not exists pgcrypto;
create table if not exists public.admin_roles(id bigint generated by default as identity primary key,role_key text unique not null,role_name text not null,description text,created_at timestamptz not null default now());
insert into public.admin_roles(id,role_key,role_name,description) values
(1,'super_admin','Super Admin','Administrador Máximo. Protegido.'),
(2,'general_admin','Administrador Geral','Gestão operacional e aprovações.'),
(3,'client_admin','Administrador de Clientes','Gestão de pedidos de clientes.')
on conflict(role_key) do update set role_name=excluded.role_name,description=excluded.description;
create table if not exists public.admin_profiles(user_id uuid primary key references auth.users(id) on delete cascade,full_name text not null,role_id bigint not null references public.admin_roles(id),role text not null,active boolean not null default true,status text not null default 'active',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.admin_invitations(id uuid primary key default gen_random_uuid(),email text not null,full_name text not null,role_id bigint not null references public.admin_roles(id),invited_by uuid references auth.users(id),status text not null default 'pending',created_at timestamptz not null default now(),expires_at timestamptz default now()+interval '7 days');
create table if not exists public.workers(id uuid primary key default gen_random_uuid(),name text not null,age integer,experience numeric default 0,category text not null,service text not null,province text not null,location text not null,phone text,bio text,status text not null default 'PENDING',reviewed_by uuid references auth.users(id),reviewed_at timestamptz,review_note text,created_at timestamptz not null default now());
create table if not exists public.jobs(id uuid primary key default gen_random_uuid(),title text not null,category text not null,service text not null,province text not null,location text not null,duration text,description text,phone text,status text not null default 'PENDING',reviewed_by uuid references auth.users(id),reviewed_at timestamptz,review_note text,created_at timestamptz not null default now());
create table if not exists public.service_requests(id uuid primary key default gen_random_uuid(),category text not null,service text not null,province text not null,location text not null,requested_date date,phone text not null,description text,status text not null default 'PENDING',reviewed_by uuid references auth.users(id),reviewed_at timestamptz,review_note text,created_at timestamptz not null default now());
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.admin_profiles where user_id=auth.uid() and active and status='active')$$;
create or replace function public.is_super_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.admin_profiles where user_id=auth.uid() and active and status='active' and role='super_admin')$$;
create or replace function public.assign_admin_by_email(p_email text,p_full_name text,p_role_id bigint) returns jsonb language plpgsql security definer set search_path=public as $$declare v_uid uuid;v_role text;begin if not public.is_super_admin() then raise exception 'Apenas o Super Admin pode atribuir perfis.';end if;select id into v_uid from auth.users where lower(email)=lower(trim(p_email)) limit 1;select role_key into v_role from public.admin_roles where id=p_role_id;if v_uid is null then raise exception 'Utilizador Auth não encontrado.';end if;if v_role is null or v_role='super_admin' then raise exception 'Perfil inválido para este fluxo.';end if;insert into public.admin_profiles(user_id,full_name,role_id,role) values(v_uid,trim(p_full_name),p_role_id,v_role) on conflict(user_id) do update set full_name=excluded.full_name,role_id=excluded.role_id,role=excluded.role,active=true,status='active',updated_at=now();return jsonb_build_object('ok',true,'user_id',v_uid,'role',v_role);end$$;
create or replace function public.set_record_status(p_table text,p_id uuid,p_status text,p_note text default null) returns boolean language plpgsql security definer set search_path=public as $$begin if not public.is_admin() then raise exception 'Acesso administrativo necessário.';end if;if p_table='workers' then update public.workers set status=upper(p_status),reviewed_by=auth.uid(),reviewed_at=now(),review_note=p_note where id=p_id;elsif p_table='jobs' then update public.jobs set status=upper(p_status),reviewed_by=auth.uid(),reviewed_at=now(),review_note=p_note where id=p_id;elsif p_table='service_requests' then update public.service_requests set status=upper(p_status),reviewed_by=auth.uid(),reviewed_at=now(),review_note=p_note where id=p_id;else raise exception 'Tabela inválida.';end if;return true;end$$;
alter table public.admin_roles enable row level security;alter table public.admin_profiles enable row level security;alter table public.admin_invitations enable row level security;alter table public.workers enable row level security;alter table public.jobs enable row level security;alter table public.service_requests enable row level security;
drop policy if exists admin_roles_read on public.admin_roles;create policy admin_roles_read on public.admin_roles for select to authenticated using(public.is_admin());
drop policy if exists admin_profiles_read on public.admin_profiles;create policy admin_profiles_read on public.admin_profiles for select to authenticated using(user_id=auth.uid() or public.is_super_admin());
drop policy if exists admin_profiles_super on public.admin_profiles;create policy admin_profiles_super on public.admin_profiles for all to authenticated using(public.is_super_admin()) with check(public.is_super_admin());
drop policy if exists invitations_super on public.admin_invitations;create policy invitations_super on public.admin_invitations for all to authenticated using(public.is_super_admin()) with check(public.is_super_admin());
drop policy if exists workers_insert on public.workers;create policy workers_insert on public.workers for insert to anon,authenticated with check(status='PENDING');
drop policy if exists workers_read on public.workers;create policy workers_read on public.workers for select to anon,authenticated using(status='APPROVED' or public.is_admin());
drop policy if exists jobs_insert on public.jobs;create policy jobs_insert on public.jobs for insert to anon,authenticated with check(status='PENDING');
drop policy if exists jobs_read on public.jobs;create policy jobs_read on public.jobs for select to anon,authenticated using(status='APPROVED' or public.is_admin());
drop policy if exists requests_insert on public.service_requests;create policy requests_insert on public.service_requests for insert to anon,authenticated with check(status='PENDING');
drop policy if exists requests_read on public.service_requests;create policy requests_read on public.service_requests for select to authenticated using(public.is_admin());
grant select,insert on public.workers,public.jobs,public.service_requests to anon,authenticated;
grant select on public.admin_roles,public.admin_profiles to authenticated;
grant select,insert,update,delete on public.admin_profiles,public.admin_invitations to authenticated;
grant execute on function public.assign_admin_by_email(text,text,bigint) to authenticated;
grant execute on function public.set_record_status(text,uuid,text,text) to authenticated;
-- SUPER ADMIN BOOTSTRAP:
-- 1) Create/confirm your account in Supabase Auth.
-- 2) Replace YOUR_SUPER_ADMIN_EMAIL below with that exact Auth email.
-- 3) Run this block once.
do $$declare v_uid uuid;begin select id into v_uid from auth.users where lower(email)=lower('YOUR_SUPER_ADMIN_EMAIL') limit 1;if v_uid is not null then insert into public.admin_profiles(user_id,full_name,role_id,role,active,status) values(v_uid,'Administrador Máximo',1,'super_admin',true,'active') on conflict(user_id) do update set full_name='Administrador Máximo',role_id=1,role='super_admin',active=true,status='active',updated_at=now();end if;end$$;